values
  ('signature-cut', (select id from public.service_categories where slug = 'hair'), 'Signature Cut & Style', 'Consultation, wash, precision cut and a blow-dry finished by hand.', 1800, false, 60, '/images/services/signature-cut.jpg', 'Stylist shaping a soft layered haircut', false, 0),
  ('balayage', (select id from public.service_categories where slug = 'hair'), 'Hand-painted Balayage', 'Sun-kissed, low-maintenance colour painted freehand, with gloss and bond care.', 7500, true, 180, '/images/services/balayage.jpg', 'Long hair with soft caramel balayage', true, 1),
  ('keratin', (select id from public.service_categories where slug = 'hair'), 'Keratin Smoothing Ritual', 'Frizz-free, glossy hair for up to four months. Formaldehyde-free formula.', 6000, true, 150, '/images/services/keratin.jpg', 'Sleek, glossy straight hair', false, 2),
  ('hydra-facial', (select id from public.service_categories where slug = 'skin'), 'Hydra Glow Facial', 'Deep cleanse, gentle exfoliation and hydration infusion for instant radiance.', 4500, false, 75, '/images/services/hydra-facial.jpg', 'Client relaxing during a facial treatment', true, 3),
  ('brow-lash', (select id from public.service_categories where slug = 'skin'), 'Brow Sculpt & Lash Lift', 'Mapped brow shaping and tint with a nourishing, curl-setting lash lift.', 2200, false, 60, '/images/services/brow-lash.jpg', 'Close-up of shaped brows and lifted lashes', false, 4),
  ('party-makeup', (select id from public.service_categories where slug = 'makeup'), 'Soft Glam Makeup', 'Skin-first, long-wear makeup for parties, shoots and receptions.', 4000, false, 75, '/images/services/party-makeup.jpg', 'Soft glam makeup with luminous skin', false, 5),
  ('gel-manicure', (select id from public.service_categories where slug = 'nails'), 'Gel Manicure', 'Cuticle care, shaping and a chip-free gel finish that lasts three weeks.', 1500, false, 50, '/images/services/gel-manicure.jpg', 'Neutral glossy gel manicure', false, 6),
  ('nail-art', (select id from public.service_categories where slug = 'nails'), 'Couture Nail Art', 'Extensions and hand-painted art, from minimalist lines to full chrome.', 2800, true, 90, '/images/services/nail-art.jpg', 'Delicate hand-painted nail art', false, 7),
  ('bridal-makeup', (select id from public.service_categories where slug = 'bridal'), 'Bridal Makeup', 'HD airbrush makeup, hairstyling and draping by our senior bridal artist.', 25000, true, 180, '/images/services/bridal-makeup.jpg', 'Bride with luminous, elegant makeup', true, 8),
  ('bridal-trial', (select id from public.service_categories where slug = 'bridal'), 'Bridal Trial', 'A full rehearsal of your wedding look, so the big day holds no surprises.', 6000, false, 120, '/images/services/bridal-trial.jpg', 'Makeup artist testing a bridal look', false, 9),
  ('aroma-massage', (select id from public.service_categories where slug = 'spa'), 'Aromatherapy Massage', 'Full-body Swedish massage with warm essential oils to melt the week away.', 3500, false, 60, '/images/services/aroma-massage.jpg', 'Calm spa room with candles and towels', false, 10),
  ('body-polish', (select id from public.service_categories where slug = 'spa'), 'Silk Body Polish', 'Sugar scrub, steam and a shea butter wrap for skin that feels like silk.', 4200, false, 90, '/images/services/body-polish.jpg', 'Bowls of body scrub and fresh petals', false, 11)
