    insert into public.testimonials (name, location, service, text, rating, sort_order) values
      ('Priya M.', 'Bandra', 'Bridal Makeup', 'I cried happy tears when I saw myself. The makeup lasted through a 14-hour wedding and still looked fresh in the last photos.', 5, 0),
      ('Sana K.', 'Khar', 'Balayage', 'Finally a colourist who listens. My balayage grew out so softly that I went four months without a touch-up.', 5, 1),
