    insert into public.faqs (question, answer, sort_order) values
      ('Do I need to book in advance?', 'We recommend booking at least two days ahead, especially for weekends. Same-day slots are released online when available.', 0),
      ('How do I reschedule or cancel?', 'Just message us on WhatsApp at least 12 hours before your slot and we''ll move it — no charge.', 1),
      ('Which products do you use?', 'Professional, cruelty-free brands chosen for each skin and hair type. We''re always happy to share exactly what we used.', 2),
      ('When should I book my bridal trial?', 'Ideally 4–8 weeks before the wedding, so there''s time to fine-tune the look and plan your pre-bridal skin prep.', 3),
      ('Do you travel for weddings?', 'Yes. Our bridal team travels across the city and for destination weddings. Travel charges depend on location.', 4),
      ('Which payment methods do you accept?', 'UPI, all major cards and cash. Bridal packages need a 25% advance to confirm the date.', 5);
